coverage=[]
for rel in FILES:
 p=PROJECT/rel;tree=ast.parse(p.read_text());entry={'file':rel,'sha256':sha(p),'line_count':len(p.read_text().splitlines()),'review':'All source text inspected, including module imports, constants, dataclasses, serialization and executable blocks. Static review is not exhaustive runtime coverage.','functions':[]}
 def walk(body,prefix=''):
  for n in body:
   if isinstance(n,ast.ClassDef):walk(n.body,prefix+n.name+'.')
   elif isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)):
    name=prefix+n.name;entry['functions'].append({'name':name,'start':n.lineno,'end':n.end_lineno,'review':notes.get(rel,{}).get(name,notes.get(rel,{}).get(n.name,'Static source review; covered by owning function/fixture where exercised.'))});walk(n.body,name+'.')
 walk(tree.body);coverage.append(entry)
